# _PyOpcode_PseudoTargets: pseudo-op -> (as_sequence, targets)
pseudo_targets = {
    LOAD_CLOSURE: (0, (LOAD_FAST,)),
    STORE_FAST_MAYBE_NULL: (0, (STORE_FAST,)),
    ANNOTATIONS_PLACEHOLDER: (0, (NOP,)),
    JUMP: (0, (JUMP_FORWARD, JUMP_BACKWARD,)),
    JUMP_NO_INTERRUPT: (0, (JUMP_FORWARD, JUMP_BACKWARD_NO_INTERRUPT,)),
    JUMP_IF_FALSE: (1, (COPY, TO_BOOL, POP_JUMP_IF_FALSE,)),
    JUMP_IF_TRUE: (1, (COPY, TO_BOOL, POP_JUMP_IF_TRUE,)),
    SETUP_FINALLY: (0, (NOP,)),
    SETUP_CLEANUP: (0, (NOP,)),
    SETUP_WITH: (0, (NOP,)),
    POP_BLOCK: (0, (NOP,)),
}


def is_pseudo_instr(op):
    return op in pseudo_targets


def is_pseudo_target(pseudo, target):
    return target in pseudo_targets.get(pseudo, (0, ()))[1]

